for (i = 0; i < opt.length; i++) if (opt[i].shanten < shMin) shMin = opt[i].shanten;
/* 听牌张数（waitsFor）只算「可能真听」的候选：13 张手牌真听 ⟹ 向听 0，
   所以最小向听 > 0 时一个都不算（34 张枚举全省），最小向听 = 0 时才逐张算。 */
if (shMin <= 0) {
  for (i = 0; i < opt.length; i++) {
    c = opt[i];
    if (c.shanten > 0) continue;
    c.waits = waitsFor(c.hand, melds, honor);
    c.waitsLeft = sumLeft(c.waits, c.hand, seen);
  }
}
var cands = [];
for (i = 0; i < opt.length; i++) if (opt[i].shanten === shMin) cands.push(opt[i]);
/* 听牌保护（唯一出口）：只要「打某张就能听 / 就能保听」，就**只在这一批里选** ——
   绝不建议打掉听口。打完真听的候选向听必然是 0（= 最小向听），所以这样收窄永远不会让向听变差。 */
var tenpaiCands = [];
for (i = 0; i < opt.length; i++) if (opt[i].waits.length > 0) tenpaiCands.push(opt[i]);
var noBetter = false, pool;
if (tenpaiCands.length) pool = tenpaiCands;
else {
  pool = cands;
  /* 一张都听不了：只有「本来已听（或按向听算已成型）」才算无解，并且要在文案里写明，绝不静默建议 */
  noBetter = !!(shBase <= 0 || tenpaiNow.length > 0);
}
pool.sort(cmpHintOpt);

